mapper.select:
SELECT pro.NAME 'project.name', pro.serial_number 'project.serial_number', pro.short_name 'project.short_name', art.serial_number 'serialNumber', art.monomer_id, art.area_id, are.`name` areaName, mon.`name` monomerName, art.`name` 'name', art.specification 'specification', art.material 'material', shop.id 'workshopId', shop.NAME 'workshopName', shop.factory_id 'factoryId', fac.`name` 'factoryName', record.print_quantity 'printQuantity', record.product_id 'productId', us.id 'printUserId', record.number 'number', record.print_time 'printTime', us.NAME 'printUserName' FROM mes_building_single_part_artifact_print_record record LEFT JOIN sys_user us ON record.print_user_id = us.id LEFT JOIN tech_artifact art ON record.product_id = art.id LEFT JOIN contract_project pro ON pro.id = art.project_id LEFT JOIN plan_area are ON are.id = art.area_id LEFT JOIN plan_monomer mon ON mon.id = art.monomer_id LEFT JOIN mes_building_workshop shop ON record.workshop_id = shop.id LEFT JOIN mes_building_factory fac ON fac.id = shop.factory_id WHERE record.bool_delete_enum = 0
AND record.product_id = #{productId}
AND record.workshop_id =#{workshopId}
